import ast

def flatten(d, parent=''):
    res = {}
    for k, v in d.items():
        key = f"{parent}.{k}" if parent else k
        if isinstance(v, dict):
            res.update(flatten(v, key))
        else:
            res[key] = v
    return res

d = ast.literal_eval(input())
res = flatten(d)
for k in res:
    print(f"{k}:{res[k]}", end=' ')

